/**
 * Adds lazy loading, async decoding and intrinsic dimensions to content images.
 *
 * MDX authors write plain markdown images, which render without width/height and
 * load eagerly. Both cost Core Web Vitals: missing dimensions cause layout shift,
 * and eager loading competes with the LCP hero for bandwidth.
 *
 * Dimensions come from `scripts/data/image-dimensions.json`, regenerated by
 * `node scripts/build-image-dimensions.mjs` whenever images change.
 */
import { visit } from 'unist-util-visit';
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { cloudFromUrl } from './cloudinary-clouds.mjs';

const MAP_PATH = join(dirname(fileURLToPath(import.meta.url)), '../data/image-dimensions.json');
const CLOUD_MAP_PATH = join(dirname(fileURLToPath(import.meta.url)), '../../src/data/gulf-image-dimensions.json');
const SIZES = existsSync(MAP_PATH) ? JSON.parse(readFileSync(MAP_PATH, 'utf8')) : {};
const CLOUD_SIZES = existsSync(CLOUD_MAP_PATH) ? JSON.parse(readFileSync(CLOUD_MAP_PATH, 'utf8')) : {};
const PREFIX = 'more-group/gulf/';
const WIDTHS = [360, 640, 960, 1200];

/**
 * Картинки внутри текста статей, которые лежат на R2.
 *
 * Плагин умел только адреса Cloudinary: на адресе R2 он не находил ни размеров кадра, ни ширин,
 * и оставлял тег как есть. Замер 21.09.2026: 205 картинок на 91 странице без width и height,
 * страница прыгала при загрузке, и ни одной ширины на выбор. Собственная проверка скорости сайта
 * ругалась на это 206 раз и была права.
 *
 * Манифест пишет scripts/r2-add-widths.mjs в корне рабочего каталога.
 */
const R2_WIDTHS_PATH = join(dirname(fileURLToPath(import.meta.url)), '../../src/data/r2-image-widths.json');
const R2_WIDTHS = existsSync(R2_WIDTHS_PATH) ? JSON.parse(readFileSync(R2_WIDTHS_PATH, 'utf8')) : {};
const R2_HOST = 'pub-2855c73eea384110b510f25966292c37.r2.dev';

function r2Attrs(src) {
  if (typeof src !== 'string') return null;
  const i = src.indexOf(R2_HOST);
  if (i < 0) return null;
  const key = src.slice(i + R2_HOST.length).replace(/^\//, '').split('?')[0];
  const entry = R2_WIDTHS[key];
  if (!entry) return null;
  const variants = (entry.variants || []).filter((w) => w < entry.w).sort((a, b) => a - b);
  const base = `https://${R2_HOST}/${key}`;
  return {
    width: entry.w,
    height: entry.h,
    srcSet: variants.length
      ? [...variants.map((w) => `${base.replace(/\.webp$/i, `-w${w}.webp`)} ${w}w`), `${base} ${entry.w}w`].join(', ')
      : null,
  };
}

function cloudPublicId(src) {
  const marker = `/${PREFIX}`;
  const index = src.indexOf(marker);
  if (!cloudFromUrl(src) || index === -1) return null;
  return src.slice(index + 1).replace(/\.(avif|gif|jpe?g|png|webp)$/i, '');
}

// The derivative keeps the cloud its source names, so a legacy image is not
// silently rewritten onto the active account or the other way round.
function deliveryUrl(publicId, width, cloud) {
  return `https://res.cloudinary.com/${cloud}/image/upload/f_auto,q_auto:low,w_${width}/${publicId}`;
}

export function rehypeImageAttrs() {
  return (tree) => {
    visit(tree, 'element', (node) => {
      if (node.tagName !== 'img') return;
      const props = (node.properties ||= {});
      if (!props.loading) props.loading = 'lazy';
      if (!props.decoding) props.decoding = 'async';
      const fromR2 = r2Attrs(props.src);
      if (fromR2) {
        if (!props.width) {
          props.width = fromR2.width;
          props.height = fromR2.height;
        }
        if (fromR2.srcSet && !props.srcSet) {
          props.srcSet = fromR2.srcSet;
          props.sizes = props.sizes || '(max-width: 599px) calc(100vw - 3rem), 72ch';
        }
        return;
      }

      const publicId = typeof props.src === 'string' ? cloudPublicId(props.src) : null;
      const dims = publicId ? CLOUD_SIZES[publicId] : (typeof props.src === 'string' ? SIZES[props.src] : null);
      if (dims && !props.width) {
        props.width = dims.width;
        props.height = dims.height;
      }
      if (publicId && dims) {
        const cloud = cloudFromUrl(props.src);
        const requested = WIDTHS.filter((width) => width <= dims.width);
        const widths = requested.length ? requested : [dims.width];
        props.src = deliveryUrl(publicId, widths.at(-1), cloud);
        props.srcSet = widths
          .map((width) => `${deliveryUrl(publicId, width, cloud)} ${width}w`)
          .join(', ');
        props.sizes = '(max-width: 599px) calc(100vw - 3rem), 72ch';
      }
    });
  };
}
